 async Task<string> Snapshot(SqliteConnection conn,string table,string[] names){await using var cmd=conn.CreateCommand();cmd.CommandText=$"SELECT {string.Join(",",names.Select(x=>$"\"{x}\""))} FROM \"{table}\" ORDER BY 1,2";await using var rows=await cmd.ExecuteReaderAsync();var values=new List<object?[]>();while(await rows.ReadAsync()){var row=new object?[names.Length];for(int i=0;i<row.Length;i++)row[i]=rows.IsDBNull(i)?null:rows.GetValue(i);values.Add(row);}return JsonSerializer.Serialize(values);}

